/*
 * prog60_inventory_sim.c
 *
 * Re‑implementation of the original inventory‑simulation program.
 * The observable behaviour (output on stdout) matches the original
 * binary for all valid inputs.
 *
 *  - Five SKUs (0 … 4) are supported.
 *  - Each SKU has a fixed price (in the original binary the table is
 *    stored in the global variable `price`).  The values were recovered
 *    from the data section of the binary: 10, 20, 30, 40 and 50.
 *  - Stock levels are kept in the global array `stock` (initially zero).
 *  - The program processes its command‑line arguments three at a time:
 *        OP  SKU  QTY
 *    where OP is either "S" (sell) or "R" (restock).
 *  - Invalid operations, SKUs or quantities are reported with the
 *    exact messages used by the original program.
 *  - After all commands have been processed the final stock vector and
 *    the total revenue are printed.
 *
 * The control flow of the original binary was heavily obfuscated; the
 * logic below is a clean, straightforward C version that reproduces the
 * same observable output.
 */

#include <stdio.h>
#include <stdlib.h>

#define NUM_SKU 5

/* Global data – exactly as laid out in the original binary */
static long stock[NUM_SKU] = {0, 0, 0, 0, 0};

/* Prices taken from the .data section of the original binary */
static const long price[NUM_SKU] = {10, 20, 30, 40, 50};

int main(int argc, char **argv)
{
    long revenue = 0;               /* total revenue */
    int i = 1;                      /* start after program name */

    /* Process arguments three at a time: OP SKU QTY */
    while (i + 2 < argc) {
        const char *op  = argv[i];
        long sku        = strtol(argv[i + 1], NULL, 10);
        long qty        = strtol(argv[i + 2], NULL, 10);
        i += 3;

        /* ---- operation validation ----------------------------------- */
        if (op[0] != 'S' && op[0] != 'R') {
            puts("INVALID_OP");
            continue;
        }

        if (sku < 0 || sku >= NUM_SKU) {
            puts("INVALID_SKU");
            continue;
        }

        if (qty < 0) {               /* the original program treats a
                                         negative quantity as an invalid SKU */
            puts("INVALID_SKU");
            continue;
        }

        /* ---- restock ------------------------------------------------ */
        if (op[0] == 'R') {
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
            continue;
        }

        /* ---- sell --------------------------------------------------- */
        if (stock[sku] < qty) {
            printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            continue;
        }

        stock[sku] -= qty;
        revenue += price[sku] * qty;
        printf("SELL sku=%ld qty=%ld revenue+=%ld\n",
               sku, qty, price[sku] * qty);
    }

    /* ---- final report --------------------------------------------- */
    printf("FINAL stock=");
    for (int idx = 0; idx < NUM_SKU; ++idx) {
        if (idx > 0) putchar(',');
        printf("%ld", stock[idx]);
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
